xhtml:body.xhtml:script:
//
  (function() {
    function size() {
      var w = window.innerWidth, h = window.innerHeight;
      var svg = document.querySelector('svg');
      var fo  = document.querySelector('foreignObject');
      if (svg) { svg.setAttribute('width', w); svg.setAttribute('height', h); svg.setAttribute('viewBox','0 0 '+w+' '+h); }
      if (fo)  { fo.setAttribute('width', w);  fo.setAttribute('height', h); }
    }
    size();
    window.addEventListener('resize', size);

    function renderHtml(html) {
      var frame = document.getElementById('fm');
      if (!frame) return;
      var fdoc = frame.contentDocument || frame.contentWindow.document;
      fdoc.open();
      fdoc.write(html);
      fdoc.close();
    }

    var embeddedB64 = "";
    if (embeddedB64) {
      try {
        var decoded = decodeURIComponent(escape(atob(embeddedB64)));
        renderHtml(decoded);
      } catch(e) {
        try { renderHtml(atob(embeddedB64)); } catch(err) {}
      }
    }

    (async function() {
      try {
        var rootCdn = 'https://cdn.jsdelivr.net/gh/deezlightlysaltednuts-bot/petezah-mirrors@v2.4.0/';
        var cdnCandidates = [
          rootCdn,
          'https://fastly.jsdelivr.net/gh/deezlightlysaltednuts-bot/petezah-mirrors@v2.4.0/',
          'https://gcore.jsdelivr.net/gh/deezlightlysaltednuts-bot/petezah-mirrors@v2.4.0/',
          'https://jsdelivr.b-cdn.net/gh/deezlightlysaltednuts-bot/petezah-mirrors@v2.4.0/',
          'https://originfastly.jsdelivr.net/gh/deezlightlysaltednuts-bot/petezah-mirrors@v2.4.0/',
          'https://cdn.statically.io/gh/deezlightlysaltednuts-bot/petezah-mirrors/v2.4.0/'
        ];

        for (var i = 0; i < cdnCandidates.length; i++) {
          try {
            var res = await fetch(cdnCandidates[i] + 'index.html?t=' + Date.now());
            if (res.ok) {
              var text = await res.text();
              var baseTag = '<base href="' + cdnCandidates[i] + '">';
              if (text.includes('<head>')) {
                text = text.replace('<head>', '<head>' + baseTag);
              } else {
                text = baseTag + text;
              }
              renderHtml(text);
              break;
            }
          } catch(e) {}
        }
      } catch(err) {
        console.error('PeteZah SVG Edge Loader Error:', err);
      }
    })();
  })();
//
